const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const slash = String.fromCharCode(92);
const quote = String.fromCharCode(34);
const escapeTag = (value) => String(value).replaceAll(slash, slash + slash).replaceAll(' ', slash + ' ').replaceAll(',', slash + ',').replaceAll('=', slash + '=');
const escapeField = (value) => String(value).replaceAll(slash, slash + slash).replaceAll(quote, slash + quote);
const writeTarget = () => {
  const org = encodeURIComponent(env.get('INFLUXDB_ORG'));
  const bucket = encodeURIComponent(env.get('INFLUXDB_BUCKET'));
  return `http://influxdb:8086/api/v2/write?org=${org}&bucket=${bucket}&precision=ns`;
};
const prepare = (payload) => ({
  payload,
  method: 'POST',
  url: writeTarget(),
  headers: {
    authorization: `Token ${env.get('INFLUXDB_ADMIN_TOKEN')}`,
    'content-type': 'text/plain; charset=utf-8',
  },
});
const reject = (reason) => {
  const timestamp = (BigInt(Date.now()) * 1000000n).toString();
  const topic = escapeTag(msg.topic || 'unknown');
  node.warn(`Telemetry rejected: ${reason}`);
  return [null, prepare(`ingestion_rejection,source=node_red,topic=${topic} count=1i,reason="${escapeField(reason)}" ${timestamp}`)];
};

let body;
try {
  if (Buffer.isBuffer(msg.payload)) body = JSON.parse(msg.payload.toString('utf8'));
  else if (typeof msg.payload === 'string') body = JSON.parse(msg.payload);
  else body = msg.payload;
} catch {
  return reject('INVALID_JSON');
}

const topic = String(msg.topic || '').split('/');
if (topic.length !== 7 || topic[0] !== 'solis' || topic[1] !== 'v1' || topic[2] !== 'tenants' || topic[4] !== 'gateways' || topic[6] !== 'telemetry') return reject('INVALID_TOPIC');
const tenantId = topic[3];
const gatewayId = topic[5];
if (!uuid.test(tenantId) || !uuid.test(gatewayId)) return reject('INVALID_TOPIC_ID');
if (!body || body.schemaVersion !== '1.0') return reject('UNSUPPORTED_SCHEMA');
if (!uuid.test(body.messageId || '') || !uuid.test(body.gatewayId || '') || !uuid.test(body.sessionId || '')) return reject('INVALID_ENVELOPE_ID');
if (body.gatewayId !== gatewayId) return reject('GATEWAY_TOPIC_MISMATCH');
if (!Number.isSafeInteger(body.sequence) || body.sequence < 0) return reject('INVALID_SEQUENCE');
if (!Number.isInteger(body.configVersion) || body.configVersion < 1) return reject('INVALID_CONFIG_VERSION');
const baseTime = Date.parse(body.sourceTime);
if (!Number.isFinite(baseTime)) return reject('INVALID_SOURCE_TIME');
if (!['SYNCED', 'UNSYNCED', 'UNKNOWN'].includes(body.clockStatus)) return reject('INVALID_CLOCK_STATUS');
if (!Array.isArray(body.samples) || body.samples.length < 1 || body.samples.length > 500) return reject('INVALID_SAMPLE_COUNT');

const lines = [];
for (const sample of body.samples) {
  if (!Number.isInteger(sample.sampleIndex) || sample.sampleIndex < 0 || sample.sampleIndex > 499) return reject('INVALID_SAMPLE_INDEX');
  if (!uuid.test(sample.variableId || '') || !uuid.test(sample.mappingId || '')) return reject('INVALID_SAMPLE_ID');
  if (!['BOOLEAN', 'INT64', 'FLOAT64', 'STRING'].includes(sample.dataType)) return reject('INVALID_DATA_TYPE');
  if (!['GOOD', 'UNCERTAIN', 'BAD', 'NO_DATA'].includes(sample.quality)) return reject('INVALID_QUALITY');
  if (typeof sample.qualityDetail !== 'string' || sample.qualityDetail.length < 1) return reject('INVALID_QUALITY_DETAIL');
  const hasValue = Object.prototype.hasOwnProperty.call(sample, 'value');
  if (sample.quality === 'NO_DATA' && hasValue) return reject('NO_DATA_HAS_VALUE');
  if (sample.quality !== 'NO_DATA' && !hasValue) return reject('VALUE_REQUIRED');

  const tags = [
    `tenant_id=${escapeTag(tenantId)}`,
    `gateway_id=${escapeTag(gatewayId)}`,
    `variable_id=${escapeTag(sample.variableId)}`,
    `quality=${escapeTag(sample.quality)}`,
    `unit_code=${escapeTag(sample.unitCode || 'none')}`,
  ];
  const fields = [
    `sequence=${body.sequence}i`,
    `sample_index=${sample.sampleIndex}i`,
    `config_version=${body.configVersion}i`,
    `message_id="${escapeField(body.messageId)}"`,
    `quality_detail="${escapeField(sample.qualityDetail)}"`,
  ];

  if (sample.quality !== 'NO_DATA') {
    if (sample.dataType === 'BOOLEAN' && typeof sample.value === 'boolean') fields.push(`value_boolean=${sample.value}`);
    else if (sample.dataType === 'INT64' && typeof sample.value === 'string' && /^-?[0-9]{1,19}$/.test(sample.value)) fields.push(`value_int64=${sample.value}i`);
    else if (sample.dataType === 'FLOAT64' && typeof sample.value === 'number' && Number.isFinite(sample.value)) fields.push(`value_float64=${sample.value}`);
    else if (sample.dataType === 'STRING' && typeof sample.value === 'string' && sample.value.length <= 256) fields.push(`value_string="${escapeField(sample.value)}"`);
    else return reject('VALUE_TYPE_MISMATCH');
  }

  const sampleTime = baseTime + (Number.isInteger(sample.offsetMs) ? sample.offsetMs : 0);
  const timestamp = (BigInt(sampleTime) * 1000000n).toString();
  lines.push(`telemetry,${tags.join(',')} ${fields.join(',')} ${timestamp}`);
}

node.status({ fill: 'green', shape: 'dot', text: `${lines.length} samples · seq ${body.sequence}` });
return [prepare(lines.join('\n')), null];
